// Paddle Input module for a breakout game.
// This module handles paddle input events and updates the ball position based on paddle reflection physics.

// Import necessary modules and types

interface Paddle {
  position: { x: number; y: number };
  width: number;
}

interface Ball {
  position: { x: number; y: number };
  velocityX: number;
  velocityY: number;
  radius: number;
}

class PaddleInput {
  private paddle: Paddle;

  constructor(paddle: Paddle) {
    this.paddle = paddle;
  }

  handleKeyDown(event: KeyboardEvent): void {
    const key = event.key;
    switch (key) {
      case 'ArrowUp':
        if (this.paddle.position.y > 0) {
          this.paddle.position.y -= 10; // Adjust velocity to simulate movement
        }
        break;
      case 'ArrowDown':
        if (this.paddle.position.y + this.paddle.width < 400) { // assuming canvas height is 400px
          this.paddle.position.y += 10; // Adjust velocity to simulate movement
        }
        break;
    }
  }
}

// Export the module function
export default PaddleInput;

