// Ball Physics module for a breakout game.
class Ball {
  public position: { x: number; y: number };
  public velocityX: number;
  public velocityY: number;
  public radius: number;

  constructor(radius = 10) {
    this.position = { x: 200, y: 200 }; // Center of the ball
    this.velocityX = Math.random() * 5; // Random horizontal speed in range (-5, 5)
    this.velocityY = Math.random() * 5 + Math.sign(Math.random()); // Vertical speed that allows bounce up or down
    this.radius = radius;
  }

  update(dt: number): void {
    this.position.x += dt * this.velocityX;
    this.position.y += dt * this.velocityY;

    // Check for collisions with walls
    if (this.position.x < 0 || this.position.x > 400) {
      this.velocityX *= -1; // Reverse horizontal direction on collision with left or right wall
    }
    if (this.position.y < 0) {
      this.velocityY *= -1;
    } else if (this.position.y > 320) {
      // Ball has gone past the paddle, reset it and change direction
      this.reset();
      this.velocityX *= -1;
    }
  }

  reset(): void {
    this.position = { x: 200, y: 200 }; // Reset ball to center of the canvas
    this.velocityX = Math.random() * 5; // Random horizontal speed in range (-5, 5)
    this.velocityY = Math.random() * 5 + Math.sign(Math.random()); // Vertical speed that allows bounce up or down
  }
}

export default Ball;

