export interface Brick {
  x: number;
  y: number;
  width: number;
  height: number;
  hitCount: number;
  color: string;
}

export interface Paddle {
  x: number;
  y: number;
  width: number;
  height: number;
  velocity: number;
  color: string;
}

export interface Ball {
  x: number;
  y: number;
  velocityX: number;
  velocityY: number;
  radius: number;
  color: string;
}

export interface GameState {
  bricks: Brick[];
  paddle: Paddle;
  ball: Ball;
  score: number;
  lives: number;
  level: number;
  highScore: number;
  gameRunning: boolean;
  gameOver: boolean;
  gameWin: boolean;
}

export function createGameState(): GameState {
  const bricks: Brick[] = [];
  const rows = 5;
  const cols = 8;
  const startX = 100;
  const startY = 20;
  const brickSize = 50;
  const gap = 10;
  const paddle = {
    x: startX + (cols * brickSize) / 2 - 40,
    y: 450,
    width: 80,
    height: 20,
    velocity: 0,
    color: '#00d9ff',
  };
  const ball = {
    x: startX + (cols * brickSize) / 2,
    y: startY + (rows * brickSize) / 2,
    velocityX: 2,
    velocityY: -2,
    radius: 6,
    color: '#ffffff',
  };
  const score = 0;
  const lives = 3;
  const level = 1;
  const highScore = 0;
  const gameRunning = true;
  const gameOver = false;
  const gameWin = false;

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      bricks.push({
        x: startX + col * (brickSize + gap),
        y: startY + row * (brickSize + gap),
        width: brickSize,
        height: brickSize,
        hitCount: 0,
        color: row === 0 ? '#ff6b6b' : row === 1 ? '#ffcc66' : row === 2 ? '#66d9ff' : row === 3 ? '#66ff66' : '#ff9f40',
      });
    }
  }

  return { bricks, paddle, ball, score, lives, level, highScore, gameRunning, gameOver, gameWin };
}

export function updateGameState(state: GameState, dt: number): GameState {
  const ball = state.ball;
  const paddle = state.paddle;
  const bricks = state.bricks;
  const score = state.score;
  const lives = state.lives;
  const gameRunning = state.gameRunning;
  const gameOver = state.gameOver;
  const gameWin = state.gameWin;

  if (!gameRunning) return state;

  // Update paddle
  const paddleSpeed = 4;
  const input = { left: false, right: false };
  if (paddle.x > 0 && paddle.x < 400 - paddle.width) {
    if (input.left) paddle.velocity = -paddleSpeed;
    if (input.right) paddle.velocity = paddleSpeed;
  } else {
    if (paddle.x > 0) paddle.velocity = -paddleSpeed;
    if (paddle.x < 400 - paddle.width) paddle.velocity = paddleSpeed;
  }
  paddle.x += paddle.velocity * dt;

  // Update ball
  ball.x += ball.velocityX * dt;
  ball.y += ball.velocityY * dt;

  // Check for wall collision
  if (ball.x < 0 || ball.x > 400 - ball.radius * 2) {
    ball.velocityX = -ball.velocityX;
  }
  if (ball.y < 0) {
    ball.velocityY = -ball.velocityY;
  }

  // Check for paddle collision
  if (ball.y > 450 && ball.y < 450 + paddle.height) {
    if (ball.x > paddle.x && ball.x < paddle.x + paddle.width) {
      ball.velocityY = -ball.velocityY;
      ball.velocityX = (ball.x - (paddle.x + paddle.width / 2)) / 20 * paddleSpeed;
      if (Math.abs(ball.velocityX) < 1) ball.velocityX = 1;
    }
  }

  // Check for brick collision
  for (let i = 0; i < bricks.length; i++) {
    const brick = bricks[i];
    if (ball.x > brick.x && ball.x < brick.x + brick.width && ball.y > brick.y && ball.y < brick.y + brick.height) {
      ball.velocityY = -ball.velocityY;
      brick.hitCount++;
      if (brick.hitCount >= 3) {
        bricks.splice(i, 1);
        i--;
      }
      score++;
      if (score >= 100) {
        gameRunning = false;
        gameOver = false;
        gameWin = true;
      }
      break;
    }
  }

  // Check for game over
  if (ball.y > 480) {
    lives--;
    if (lives === 0) {
      gameRunning = false;
      gameOver = true;
    } else {
      ball.x = 200;
      ball.y = 450;
      ball.velocityX = 2;
      ball.velocityY = -2;
      paddle.x = 200;
    }
  }

  return { ...state, ball, paddle, score, lives, gameRunning, gameOver, gameWin };
}

import { GameState, createGameState, updateGameState } from '../game-state/game-state.ts';

const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 600;
document.body.appendChild(canvas);

const ctx = canvas.getContext('2d');

let ball = { x: 200, y: 300, vx: 4, vy: -4, radius: 6 };
let paddle = { x: 180, y: 550, width: 100, height: 20, velocity: 0 };
let bricks = [];
let score = 0;
let lives = 3;
let gameOver = false;

const brickRows = 5;
const brickCols = 8;
const brickSize = 50;
const brickGap = 10;

function createBricks() {
  bricks = [];
  const startX = 100;
  const startY = 50;
  for (let row = 0; row < brickRows; row++) {
    for (let col = 0; col < brickCols; col++) {
      bricks.push({
        x: startX + col * (brickSize + brickGap),
        y: startY + row * (brickSize + brickGap),
        width: brickSize,
        height: brickSize,
        color: row === 0 ? 'red' : row === 1 ? 'orange' : row === 2 ? 'yellow' : row === 3 ? 'green' : 'blue'
      });
    }
  }
}

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.closePath();
}

function drawPaddle() {
  ctx.fillStyle = '#00d9ff';
  ctx.fillRect(paddle.x, paddle.y, paddle.width, paddle.height);
}

function drawBricks() {
  bricks.forEach(brick => {
    ctx.fillStyle = brick.color;
    ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
  });
}

function drawScore() {
  ctx.fillStyle = '#ffffff';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function drawLives() {
  ctx.fillStyle = '#ffffff';
  ctx.font = '20px Arial';
  ctx.fillText(`Lives: ${lives}`, 350, 30);
}

function update() {
  if (gameOver) return;

  ball.x += ball.vx;
  ball.y += ball.vy;

  // Wall collision
  if (ball.x - ball.radius < 0 || ball.x + ball.radius > 400) {
    ball.vx = -ball.vx;
  }

  // Paddle collision
  if (ball.y > 550 && ball.y < 550 + paddle.height) {
    if (ball.x > paddle.x && ball.x < paddle.x + paddle.width) {
      ball.vy = -ball.vy;
      ball.vx = (ball.x - (paddle.x + paddle.width / 2)) / 20 * 3;
      if (Math.abs(ball.vx) < 1) ball.vx = 1;
    }
  }

  // Brick collision
  bricks.forEach(brick => {
    if (ball.x > brick.x && ball.x < brick.x + brick.width && ball.y > brick.y && ball.y < brick.y + brick.height) {
      ball.vy = -ball.vy;
      bricks.splice(bricks.indexOf(brick), 1);
      score++;
      if (bricks.length === 0) {
        gameOver = true;
      }
      return;
    }
  });

  // Game over
  if (ball.y > 580) {
    lives--;
    if (lives === 0) {
      gameOver = true;
    } else {
      ball.x = 200;
      ball.y = 580;
      ball.vx = 4;
      ball.vy = -4;
      paddle.x = 180;
    }
  }
}

function render() {
  ctx.clearRect(0, 0, 400, 600);
  drawBall();
  drawPaddle();
  drawBricks();
  drawScore();
  drawLives();
  requestAnimationFrame(render);
}

function movePaddle() {
  if (paddle.velocity > 0) {
    paddle.x += paddle.velocity;
    if (paddle.x + paddle.width > 400) {
      paddle.x = 400 - paddle.width;
    }
  } else if (paddle.velocity < 0) {
    paddle.x += paddle.velocity;
    if (paddle.x < 0) {
      paddle.x = 0;
    }
  }
}

function init() {
  createBricks();
  render();
  setInterval(() => { movePaddle(); }, 16);
}

init();
